-- Read-only. Reuse this exact cutoff after deployment; never rewrite frozen rows.
with cutoff as (select timestamptz '2026-11-23 00:42:14.777036+00' as at), datasets as (
select 'NBA_PREDICTION_INPUTS' name,count(*) rows,md5(coalesce(string_agg(jsonb_build_array(p.id,p.game_id,p.commence_time,p.home_team,p.away_team,p.team,p.opponent,p.market,p.sportsbook,p.odds,p.implied_probability,p.model_probability,p.edge,p.ev,p.confidence,p.recommended_pick,p.created_at,p.selection,p.line,p.projected_line,p.odds_timestamp,p.generated_at,p.cutoff_at,p.model_version,p.feature_snapshot,p.validation_warnings,p.validation_status,p.production_eligible,p.is_current,p.model_role,p.official_pick_at_lock)::text,'' order by p.id),'')) fingerprint from public.prediction_history p,cutoff c where p.sport_key='basketball_nba' and p.created_at<=c.at
union all select 'DECISION_V1_FORECASTS',count(*),md5(coalesce(string_agg(to_jsonb(f)::text,'' order by f.forecast_id),'')) from public.nba_decision_shadow_forecasts_v1 f,cutoff c where f.inserted_at<=c.at
union all select 'DECISION_V1_OUTCOMES',count(*),md5(coalesce(string_agg(to_jsonb(o)::text,'' order by o.forecast_id),'')) from public.nba_decision_shadow_outcomes_v1 o,cutoff c where o.settled_at<=c.at
union all select 'DECISION_V2_FORECASTS',count(*),md5(coalesce(string_agg(to_jsonb(f)::text,'' order by f.id),'')) from nba_v2_shadow.forecasts f join nba_v2_shadow.cycles cy on cy.id=f.cycle_id,cutoff c where cy.captured_at<=c.at
union all select 'DECISION_V2_JUDGMENTS',count(*),md5(coalesce(string_agg(to_jsonb(j)::text,'' order by j.cycle_id,j.forecast_id),'')) from nba_v2_shadow.judgments j join nba_v2_shadow.cycles cy on cy.id=j.cycle_id,cutoff c where cy.captured_at<=c.at
) select (select at from cutoff) as cutoff_at,jsonb_agg(to_jsonb(d) order by name) as datasets from datasets d;
